package com.xyz.question_bank_management_system.modules.course.controller;
import com.xyz.question_bank_management_system.common.ApiResponse;import com.xyz.question_bank_management_system.modules.course.service.*;import com.xyz.question_bank_management_system.util.SecurityContextUtil;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequiredArgsConstructor @PreAuthorize("hasRole('STUDENT')") public class LearningOutcomeController {private final CourseProgressService progressService;private final ExamEligibilityService eligibilityService;private final LearningReportService reportService;@GetMapping("/api/v1/courses/{courseId}/progress")public ApiResponse<Map<String,Object>> progress(@PathVariable Long courseId){return ApiResponse.ok(progressService.progress(SecurityContextUtil.getUserId(),courseId));}@GetMapping("/api/v1/training-goals/{goalId}/exam-eligibility")public ApiResponse<Map<String,Object>> eligibility(@PathVariable Long goalId){return ApiResponse.ok(eligibilityService.eligibility(SecurityContextUtil.getUserId(),goalId));}@GetMapping("/api/v1/students/me/learning-report")public ApiResponse<Map<String,Object>> report(@RequestParam Long courseId){return ApiResponse.ok(reportService.report(SecurityContextUtil.getUserId(),courseId));}}
